function debounceAsync(fn, delay) {
    let timeoutId;
    let abortController;

    return function (...args) {
        // Clear the previous timeout if it exists
        if (timeoutId) {
            clearTimeout(timeoutId);
            if (abortController) {
                abortController.abort(); // Abort the previous call
            }
        }

        // Create a new AbortController for the new call
        abortController = new AbortController();
        const { signal } = abortController;

        // Set a timeout to call the function after the delay
        timeoutId = setTimeout(async () => {
            try {
                await fn(...args, { signal }); // Call the function with the current arguments and signal
            } catch (error) {
                if (error.name === 'AbortError') {
                    console.log('Operation was cancelled.'); // Handle the abort error
                } else {
                    console.error('Error during function execution:', error); // Handle other errors
                }
            }
        }, delay);
    };
}

